function getGlsPointType(point) {
	var type = '';

	if (point) {
		type = point.type || point.pointType || point.locationType || '';

		if (!type && point.name && (point.name.toLowerCase().indexOf('paketomat') !== -1 || point.name.toLowerCase().indexOf('locker') !== -1)) {
			type = 'parcel-locker';
		}
	}

	type = String(type).toLowerCase();

	if (type.indexOf('locker') !== -1 || type.indexOf('paketomat') !== -1) {
		return 'parcel-locker';
	}

	if (type.indexOf('shop') !== -1) {
		return 'parcel-shop';
	}

	return type;
}

