if (!$gls_locker && isset($this->session->data['shipping_method']['code']) && $this->session->data['shipping_method']['code'] == 'gls.gls' && !empty($this->session->data['gls'])) {
	$gls_locker = stripos($this->session->data['gls'], 'paketomat') !== false || stripos($this->session->data['gls'], 'locker') !== false;
}

if ($gls_locker) {
