}

$gls_locker = isset($this->session->data['shipping_method']['code']) && $this->session->data['shipping_method']['code'] == 'gls.gls' && isset($this->session->data['gls_type']) && $this->session->data['gls_type'] == 'parcel-locker';

if (!$gls_locker && isset($this->session->data['shipping_method']['code']) && $this->session->data['shipping_method']['code'] == 'gls.gls' && !empty($this->session->data['gls'])) {
